def parse_house_positions(file_path):
    with open(file_path, 'r') as f:
        lines = f.read().splitlines()
    road_idx = None
    for i, line in enumerate(lines):
        if '-' in line:
            road_idx = i
            break
    if road_idx is None:
        raise ValueError('Road line not found')
    positions = set()
    for adj in [road_idx - 1, road_idx + 1]:
        if 0 <= adj < len(lines):
            for pos, ch in enumerate(lines[adj]):
                if ch == 'H':
                    positions.add(pos)
    return sorted(positions)

